class Solution {
public:
    int surfaceArea(vector<vector<int>>& grid) {
        int n = grid.size();
        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int v = grid[i][j];
                if (v > 0) {
                    ans += 2 + 4 * v;
                    if (i > 0) ans -= 2 * min(v, grid[i - 1][j]);
                    if (j > 0) ans -= 2 * min(v, grid[i][j - 1]);
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int surfaceArea(int[][] grid) {
        int n = grid.length;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int v = grid[i][j];
                if (v > 0) {
                    ans += 2 + 4 * v;
                    if (i > 0) ans -= 2 * Math.min(v, grid[i - 1][j]);
                    if (j > 0) ans -= 2 * Math.min(v, grid[i][j - 1]);
                }
            }
        }
        return ans;
    }
}

var surfaceArea = function(grid) {
    const n = grid.length;
    let ans = 0;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const v = grid[i][j];
            if (v > 0) {
                ans += 2 + 4 * v;
                if (i > 0) ans -= 2 * Math.min(v, grid[i - 1][j]);
